import java.text.*;import java.util.*;
class MessagesJa extends ListResourceBundle{protected Object[][] getContents(){return new Object[][]{{"greeting","こんにちは、{0}さん"}};}}class MessagesEn extends ListResourceBundle{protected Object[][] getContents(){return new Object[][]{{"greeting","Hello, {0}"}};}}
public class Main {public static void main(String[] args){Scanner s=new Scanner(System.in);String lang=s.next(),name=s.next();ResourceBundle b=lang.equals("ja")?new MessagesJa():new MessagesEn();System.out.println(MessageFormat.format(b.getString("greeting"),name));}}
